package engine

import (
	"fmt"
	"strings"
)

// Secrets (sx): secret doors and false walls, shortcuts between halls, hidden floor panels and
// trapdoors (dropping into a vault below), hollow statues/altars/wells/trees/pillars with caches,
// clue inscriptions, a secret-keeper rumour on villagers and a sidebar sense line.
//
// Everything is generated by a zone hook from side rngs (seed:sx:zoneKey) and recorded in
// g.ext("sx") (planet-local: zone keys repeat across planets). A hidden door is a plain wall (or
// rock) until found, then it becomes a door, so rendering is untouched. Finding: passive
// Perception hint in the minute hook, the `s` search within 2 tiles (sxSearch), knocking on a wall
// or tapping a container (sxBump), reading a clue inscription, or a rumour. Hooks to wire are
// listed in the report: sxBump (MoveP) and sxSearch (`s` key).

const (
	sxRoomP  = 0.7  // dungeon level has a hidden chamber
	sxCutP   = 0.4  // dungeon level has a secret shortcut
	sxPanelP = 0.4  // dungeon level (above the last) has a trapdoor panel
	sxCool   = 60   // minutes before the same wall/container can be tried again by bumping
	sxClueP  = 0.65 // a clue inscription is carved for a secret
)

type sxSecret struct {
	K     string `json:"k"` // door cut panel vault hollow
	X     int    `json:"x,omitempty"`
	Y     int    `json:"y,omitempty"`
	Fx    int    `json:"fx,omitempty"` // floor tile on the near side (door, cut, vault)
	Fy    int    `json:"fy,omitempty"`
	Ix    int    `json:"ix,omitempty"` // hidden room centre
	Iy    int    `json:"iy,omitempty"`
	N     string `json:"n,omitempty"` // container kind (key of sxContainerNames)
	L     string `json:"l,omitempty"` // container label for hints
	Order string `json:"o,omitempty"` // a secret order's lodge
	Clue  int    `json:"c,omitempty"` // tile index of the clue inscription
	Found bool   `json:"f,omitempty"`
	Hint  bool   `json:"h,omitempty"`
	Told  bool   `json:"t,omitempty"`
	Try   int    `json:"tr,omitempty"` // minute of the last bump roll
	Tried bool   `json:"td,omitempty"`
}

type sxZone struct {
	S []*sxSecret `json:"s"`
}

type sxState struct {
	Z     map[string]*sxZone `json:"z"`
	Told  map[string]bool    `json:"told,omitempty"`  // zone keys a rumour pointed at
	Asked map[string]int     `json:"asked,omitempty"` // keepers already asked
	Deed  map[string]bool    `json:"deed,omitempty"`
	N     int                `json:"n,omitempty"`
}

func init() {
	zoneHooks = append(zoneHooks, sxZoneHook)
	turnHooks = append(turnHooks, sxTurn)
	talkHooks = append(talkHooks, sxTalk)
	sideHooks = append(sideHooks, sxSide)
	unLocalKeys = append(unLocalKeys, "sx")
}

func sxSt(g *Game) *sxState {
	st := g.ext("sx", func() any { return &sxState{} }).(*sxState)
	if st.Z == nil {
		st.Z = map[string]*sxZone{}
	}
	if st.Told == nil {
		st.Told = map[string]bool{}
	}
	if st.Asked == nil {
		st.Asked = map[string]int{}
	}
	if st.Deed == nil {
		st.Deed = map[string]bool{}
	}
	return st
}

// sxRoll is a pure [0,1) value from seed, purpose and key (rumours predict levels with it).
func sxRoll(g *Game, key, what string) float64 {
	return float64(HashStr(g.W.Seed+":sx:"+what+":"+key)>>11) / float64(1<<53)
}

func sxHasPanel(g *Game, upperKey string) bool { return sxRoll(g, upperKey, "panel") < sxPanelP }

// ---- tile tests ----

func sxSolid(t Terrain) bool { return t == TWall || t == TRock }

func sxFloorOK(zn *Zone, x, y int) bool {
	if !zn.In(x, y) {
		return false
	}
	t := zn.At(x, y)
	switch t {
	case TDown, TUp, TDoor, TDoorOpen, TLocked, TTrap, TPortal, TLava, TChasm, TVoid:
		return false
	}
	d := t.D()
	return d.Walk && d.Water == 0
}

func sxPassable(zn *Zone, x, y int) bool {
	if !zn.In(x, y) {
		return false
	}
	t := zn.At(x, y)
	return t.D().Walk || t == TDoor || t == TDoorOpen || t == TLocked
}

// sxDist is the 4-way walking distance between two tiles (-1 when unreachable).
func sxDist(zn *Zone, ax, ay, bx, by int) int {
	dist := make([]int16, MW*MH)
	for i := range dist {
		dist[i] = -1
	}
	q := []int{ay*MW + ax}
	dist[q[0]] = 0
	for len(q) > 0 {
		c := q[0]
		q = q[1:]
		x, y := c%MW, c/MW
		if x == bx && y == by {
			return int(dist[c])
		}
		for _, d := range [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
			nx, ny := x+d[0], y+d[1]
			if !sxPassable(zn, nx, ny) || dist[ny*MW+nx] >= 0 {
				continue
			}
			dist[ny*MW+nx] = dist[c] + 1
			q = append(q, ny*MW+nx)
		}
	}
	return -1
}

var sxDirs4 = [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

// sxSpot is a candidate hidden room: the wall tile D, the floor F on the near side and the
// interior rectangle (inclusive) beyond it.
type sxSpot struct {
	dx, dy, fx, fy, x0, y0, x1, y1 int
	annex                          bool
}

func sxFindRoom(zn *Zone, r *Rng, depth, breadth int, annex bool) (sxSpot, bool) {
	for try := 0; try < 400; try++ {
		dx, dy := r.Int(2, MW-3), r.Int(2, MH-3)
		d := sxDirs4[r.Int(0, 3)]
		t := zn.At(dx, dy)
		if annex && t != TWall || !annex && !sxSolid(t) {
			continue
		}
		if _, ok := zn.Notes[dy*MW+dx]; ok {
			continue
		}
		if !sxFloorOK(zn, dx-d[0], dy-d[1]) {
			continue
		}
		px, py := -d[1], d[0]
		hb := breadth / 2
		x0, y0, x1, y1 := 1<<30, 1<<30, -1, -1
		for k := 1; k <= depth; k++ {
			for j := -hb; j <= hb; j++ {
				x, y := dx+d[0]*k+px*j, dy+d[1]*k+py*j
				x0, y0, x1, y1 = mini(x0, x), mini(y0, y), maxi(x1, x), maxi(y1, y)
			}
		}
		if x0 < 2 || y0 < 2 || x1 > MW-3 || y1 > MH-3 {
			continue
		}
		ok := true
		for y := y0 - 1; y <= y1+1 && ok; y++ {
			for x := x0 - 1; x <= x1+1; x++ {
				t := zn.At(x, y)
				inside := x >= x0 && x <= x1 && y >= y0 && y <= y1
				switch {
				case !annex:
					ok = sxSolid(t)
				case inside:
					ok = (t == TGrass || t == TDirt || t == TTallGrass) && zn.ActorAt(x, y) == nil && len(zn.ItemsAt(x, y)) == 0
				default:
					ok = t == TGrass || t == TDirt || t == TTallGrass || t == TWall
				}
				if _, has := zn.Notes[y*MW+x]; has {
					ok = false
				}
				if !ok {
					break
				}
			}
		}
		if ok {
			return sxSpot{dx, dy, dx - d[0], dy - d[1], x0, y0, x1, y1, annex}, true
		}
	}
	return sxSpot{}, false
}

// ---- generation ----

func sxGold(g *Game, n, x, y int) *Item {
	return &Item{ID: g.newID(), Kind: "gold", Name: g.Sk.Currency, Glyph: '$', F: CYellow, Count: n, X: x, Y: y}
}

// sxMakeRoom carves (or builds) a hidden room behind a wall, fills it and returns the secret.
func sxMakeRoom(g *Game, zn *Zone, r *Rng, kind string, tier int, allowAnnex, force bool, foes []string) *sxSecret {
	depth, breadth := r.Int(2, 3), r.Int(3, 5)
	if kind == "vault" {
		depth, breadth = 3, 5
	}
	sp, ok := sxFindRoom(zn, r, depth, breadth, false)
	if !ok && allowAnnex {
		sp, ok = sxFindRoom(zn, r, depth, breadth, true)
	}
	if !ok {
		return nil
	}
	floor := zn.At(sp.fx, sp.fy)
	if sp.annex {
		floor = TFloor
		for y := sp.y0 - 1; y <= sp.y1+1; y++ {
			for x := sp.x0 - 1; x <= sp.x1+1; x++ {
				if (x != sp.dx || y != sp.dy) && zn.At(x, y) != TWall {
					zn.Set(x, y, TWall)
				}
			}
		}
	}
	for y := sp.y0; y <= sp.y1; y++ {
		for x := sp.x0; x <= sp.x1; x++ {
			zn.Set(x, y, floor)
		}
	}
	cx, cy := (sp.x0+sp.x1)/2, (sp.y0+sp.y1)/2
	s := &sxSecret{K: kind, X: sp.dx, Y: sp.dy, Fx: sp.fx, Fy: sp.fy, Ix: cx, Iy: cy}
	spot := func() (int, int) { return r.Int(sp.x0, sp.x1), r.Int(sp.y0, sp.y1) }
	n := 2
	if kind == "vault" || force {
		n = 3
	}
	for i := 0; i < n; i++ {
		it := g.Loot(r, tier)
		it.X, it.Y = spot()
		zn.Items = append(zn.Items, it)
	}
	gx, gy := spot()
	zn.Items = append(zn.Items, sxGold(g, 12*(zn.Level+2)+r.Int(0, 40)+30*sxBoolInt(kind == "vault"), gx, gy))
	if au := g.augLoot(zn.Key+":sx:"+kind, 0.25); au != nil {
		au.X, au.Y = spot()
		zn.Items = append(zn.Items, au)
	}
	// a guardian or a trap
	if kind != "vault" && r.Chance(0.3) {
		id := ""
		if len(foes) > 0 {
			id = Pick(r, foes)
		} else {
			id = pickCreature(r, zn.Biome, 'd', zn.Level)
		}
		a := g.Spawn(id, zn.Level+1, r)
		a.X, a.Y = spot()
		zn.Actors = append(zn.Actors, a)
	}
	if r.Chance(0.25) {
		if zn.Traps == nil {
			zn.Traps = map[int]uint8{}
		}
		x, y := sp.x0+(sp.dx-sp.x0), sp.y0+(sp.dy-sp.y0)
		x, y = clampi(x, sp.x0, sp.x1), clampi(y, sp.y0, sp.y1)
		zn.Traps[y*MW+x] = uint8(r.Int(1, 3))
	}
	return s
}

func sxBoolInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// sxMakeCut finds a thin wall between two far-apart (or unconnected) walkable places.
func sxMakeCut(zn *Zone, r *Rng) *sxSecret {
	bfs := 0
	for try := 0; try < 500 && bfs < 30; try++ {
		dx, dy := r.Int(2, MW-3), r.Int(2, MH-3)
		d := sxDirs4[r.Int(0, 3)]
		if !sxSolid(zn.At(dx, dy)) {
			continue
		}
		if _, ok := zn.Notes[dy*MW+dx]; ok {
			continue
		}
		ax, ay, bx, by := dx-d[0], dy-d[1], dx+d[0], dy+d[1]
		if !sxFloorOK(zn, ax, ay) || !sxFloorOK(zn, bx, by) {
			continue
		}
		bfs++
		if n := sxDist(zn, ax, ay, bx, by); n >= 0 && n < 24 {
			continue
		}
		return &sxSecret{K: "cut", X: dx, Y: dy, Fx: ax, Fy: ay, Ix: bx, Iy: by}
	}
	return nil
}

func sxCompass(dx, dy int) string {
	n, e := "", ""
	switch {
	case dy*2 < -abs(dx):
		n = "north"
	case dy*2 > abs(dx):
		n = "south"
	}
	switch {
	case dx*2 > abs(dy):
		e = "east"
	case dx*2 < -abs(dy):
		e = "west"
	}
	switch {
	case n != "" && e != "":
		return n + "-" + e
	case n != "":
		return n
	case e != "":
		return e
	}
	return "here"
}

func sxAbbrev(dir string) string {
	r := strings.NewReplacer("north", "N", "south", "S", "east", "E", "west", "W", "-", "")
	return r.Replace(dir)
}

func sxFar(d int) string {
	switch {
	case d <= 6:
		return "a few paces"
	case d <= 16:
		return "a dozen paces"
	}
	return "a long walk"
}

func sxUpper(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// sxAnchor is a walkable tile from which a clue can be read for a secret.
func sxAnchor(zn *Zone, s *sxSecret) (int, int) {
	switch s.K {
	case "door", "cut", "vault":
		return s.Fx, s.Fy
	case "panel":
		return s.X, s.Y
	}
	for _, d := range dirs8 {
		if sxFloorOK(zn, s.X+d[0], s.Y+d[1]) {
			return s.X + d[0], s.Y + d[1]
		}
	}
	return s.X, s.Y
}

// sxPlaceClue carves an inscription on a floor tile in the open within reach of the secret.
func sxPlaceClue(zn *Zone, r *Rng, s *sxSecret) {
	ax, ay := sxAnchor(zn, s)
	for try := 0; try < 80; try++ {
		x, y := ax+r.Int(-14, 14), ay+r.Int(-8, 8)
		d := maxi(abs(x-s.X), abs(y-s.Y))
		if d < 3 || !sxFloorOK(zn, x, y) || len(zn.ItemsAt(x, y)) > 0 || zn.ActorAt(x, y) != nil {
			continue
		}
		if _, has := zn.Traps[y*MW+x]; has {
			continue
		}
		if _, has := zn.Notes[y*MW+x]; has {
			continue
		}
		open, bad := 0, false
		for _, dd := range dirs8 {
			t := zn.At(x+dd[0], y+dd[1])
			if t.D().Walk {
				open++
			}
			if t == TDoor || t == TDown || t == TUp || t == TLocked {
				bad = true
			}
		}
		if open < 6 || bad {
			continue
		}
		if dist := sxDist(zn, ax, ay, x, y); dist < 0 || dist > 40 {
			continue
		}
		line := Pick(r, sxClueLines[s.K])
		line = strings.NewReplacer("{dir}", sxCompass(s.X-x, s.Y-y), "{far}", sxFar(d)).Replace(line)
		zn.Set(x, y, TInscription)
		zn.Notes[y*MW+x] = sxUpper(line)
		s.Clue = y*MW + x
		return
	}
}

func sxContainerKind(t Terrain) (kind, label string) {
	switch t {
	case TStatue:
		return "statue", "statue"
	case TAltar:
		return "altar", "altar"
	case TWell:
		return "well", "well"
	case TTree, TDeadTree:
		return "tree", "tree"
	case TPillar:
		return "pillar", "pillar"
	case TShelf:
		return "shelf", "shelf"
	case TSarcophagus:
		return "sarcoph", "sarcophagus"
	}
	return "", ""
}

// sxBellTower: a landmark tower's corner pillar (brazier in the middle, pillars at the corners).
func sxBellTower(zn *Zone, x, y int) bool {
	for _, a := range []int{-3, -2, 2, 3} {
		for _, b := range []int{-3, -2, 2, 3} {
			if zn.At(x+a, y+b) == TBrazier && zn.At(x+2*a, y) != TBrazier {
				return true
			}
		}
	}
	return false
}

func sxMakeHollow(g *Game, zn *Zone, r *Rng, nz *sxZone, p float64, types []Terrain, bells bool) {
	if sxRoll(g, zn.Key, "hollow") >= p {
		return
	}
	var cands, altars, bell []int
	for i, t := range zn.T {
		x, y := i%MW, i/MW
		for _, want := range types {
			if t == want {
				cands = append(cands, i)
				if t == TAltar {
					altars = append(altars, i)
				}
			}
		}
		if bells && t == TPillar && sxBellTower(zn, x, y) {
			bell = append(bell, i)
		}
	}
	taken := map[int]bool{}
	mk := func(i int, kind, label string) {
		if taken[i] {
			return
		}
		taken[i] = true
		nz.S = append(nz.S, &sxSecret{K: "hollow", X: i % MW, Y: i / MW, N: kind, L: label})
	}
	if len(cands) > 0 {
		i := Pick(r, cands)
		if len(altars) > 0 && r.Chance(0.6) {
			i = Pick(r, altars)
		}
		kind, label := sxContainerKind(zn.T[i])
		mk(i, kind, label)
	} else {
		r.Int(0, 1)
	}
	if len(bell) > 0 && r.Chance(0.5) {
		mk(Pick(r, bell), "bell", "bell-tower pillar")
	}
}

func sxZoneHook(g *Game, zn *Zone, _ *Rng) {
	if g.W == nil || zn == nil {
		return
	}
	st := sxSt(g)
	key := zn.Key
	r := NewRng(g.W.Seed + ":sx:" + key)
	nz := &sxZone{}
	var foes []string
	switch zn.Kind {
	case "dungeon":
		site := g.siteAt(zn.WX, zn.WY, zn.ZX, zn.ZY)
		if site != nil {
			foes = themes[site.Theme].foes
		}
		tier := zn.Level/3 + 2
		var first *sxSecret
		if sxRoll(g, key, "room") < sxRoomP {
			if s := sxMakeRoom(g, zn, r, "door", tier, false, false, foes); s != nil {
				nz.S = append(nz.S, s)
				first = s
			}
		}
		if sxRoll(g, key, "room2") < 0.25 {
			if s := sxMakeRoom(g, zn, r, "door", tier, false, false, foes); s != nil {
				nz.S = append(nz.S, s)
			}
		}
		if sxRoll(g, key, "cut") < sxCutP {
			if s := sxMakeCut(zn, r); s != nil {
				nz.S = append(nz.S, s)
			}
		}
		if zn.Z >= 2 && sxHasPanel(g, ZoneKey(zn.WX, zn.WY, zn.ZX, zn.ZY, zn.Z-1)) {
			if s := sxMakeRoom(g, zn, r, "vault", tier+1, false, true, nil); s != nil {
				nz.S = append(nz.S, s)
			}
		}
		if site != nil && zn.Z < site.Depth && sxHasPanel(g, key) {
			if x, y, ok := zn.FreeSpot(r, func(x, y int) bool {
				if !sxFloorOK(zn, x, y) || len(zn.ItemsAt(x, y)) > 0 {
					return false
				}
				if _, has := zn.Traps[y*MW+x]; has {
					return false
				}
				for _, d := range dirs8 {
					if t := zn.At(x+d[0], y+d[1]); t == TDown || t == TUp || t == TDoor {
						return false
					}
				}
				return true
			}); ok {
				nz.S = append(nz.S, &sxSecret{K: "panel", X: x, Y: y})
			}
		}
		sxMakeHollow(g, zn, r, nz, 0.3, []Terrain{TStatue, TSarcophagus, TShelf, TPillar}, false)
		if first != nil && st.Told[key] {
			first.Told = true
		}
	case "town", "ruin", "crypt", "wonder", "outskirts":
		p := map[string]float64{"town": 0.3, "ruin": 0.45, "crypt": 0.5, "wonder": 0.3, "outskirts": 0.15}[zn.Kind]
		tier := zn.Level/3 + 1
		var lodge *Order
		var bd *BurgData
		if zn.Kind == "town" && zn.Z == 0 && zn.Burg >= 0 {
			bd = g.W.burgByID[zn.Burg]
			for _, o := range g.Orders() {
				if o.Secret && o.Burg == zn.Burg && o.ZX == zn.ZX && o.ZY == zn.ZY && sxRoll(g, o.ID+key, "lodge") < 0.8 {
					lodge = o
					break
				}
			}
		}
		if lodge != nil || sxRoll(g, key, "room") < p {
			if s := sxMakeRoom(g, zn, r, "door", tier, true, lodge != nil, nil); s != nil {
				if lodge != nil && bd != nil {
					s.Order = lodge.ID
					cu := g.W.cultByID[bd.Culture]
					a := g.makeNPC("villager", bd, cu, r)
					a.Title = "member"
					a.Set("ordm:" + lodge.ID)
					a.AI = "still"
					a.X, a.Y = s.Ix, s.Iy
					a.HomeX, a.HomeY = a.X, a.Y
					zn.Actors = append(zn.Actors, a)
				}
				nz.S = append(nz.S, s)
			}
		}
		sxMakeHollow(g, zn, r, nz, 0.45, []Terrain{TStatue, TAltar, TWell}, zn.Kind == "town")
	case "tower":
		sxMakeHollow(g, zn, r, nz, 0.5, []Terrain{TStatue, TShelf, TPillar}, false)
	case "surface", "lair", "camp":
		sxMakeHollow(g, zn, r, nz, 0.1, []Terrain{TTree, TDeadTree}, false)
	}
	for _, s := range nz.S {
		if s.K != "hollow" && sxRoll(g, key+fmt.Sprint(s.X, s.Y), "clue") < sxClueP {
			sxPlaceClue(zn, r, s)
		}
	}
	if old := st.Z[key]; old != nil { // regenerated zone: keep what the player already learned
		for _, s := range nz.S {
			for _, o := range old.S {
				if o.K == s.K && o.X == s.X && o.Y == s.Y {
					s.Found, s.Hint, s.Told = o.Found, o.Hint, o.Told
					if s.Found {
						sxApplyFound(zn, s)
					}
				}
			}
		}
	}
	if len(nz.S) == 0 {
		delete(st.Z, key)
		return
	}
	st.Z[key] = nz
}

// sxApplyFound is the visible effect of a found secret (also used when a zone is rebuilt).
func sxApplyFound(zn *Zone, s *sxSecret) {
	switch s.K {
	case "door", "cut", "vault":
		zn.Set(s.X, s.Y, TDoor)
	case "panel":
		zn.Set(s.X, s.Y, TTrap)
	}
}

// ---- finding ----

// sxMod: Perception (INT, thoughts) plus Survival and Lore ranks.
func sxMod(g *Game) int {
	return g.checkMod("perception") + g.Skills["survival"] + g.Skills["lore"]
}

func sxDC(zn *Zone, s *sxSecret) int {
	dc := 11 + mini(zn.Level/4, 5)
	switch s.K {
	case "cut", "hollow":
		dc--
	case "vault":
		dc++
	}
	return dc
}

func sxHere(g *Game) *sxZone {
	if g.Cur == nil || g.W == nil {
		return nil
	}
	return sxSt(g).Z[g.Cur.Key]
}

func sxHintMsg(g *Game, s *sxSecret) {
	lines := sxHintLines[s.K]
	if len(lines) == 0 {
		return
	}
	line := lines[int(HashStr(g.W.Seed+fmt.Sprint(s.X, s.Y, g.Cur.Key, "hint")))%len(lines)]
	if strings.Contains(line, "%s") {
		line = fmt.Sprintf(line, s.L)
	}
	g.Msg("{{c|" + line + "}}")
}

func sxFirst(g *Game, kind, text string) {
	st := sxSt(g)
	if st.Deed[kind] {
		return
	}
	st.Deed[kind] = true
	g.deed("discovery", text, 0, 0)
}

// sxReveal marks a secret found and applies its effect.
func sxReveal(g *Game, zn *Zone, s *sxSecret) {
	if s.Found {
		return
	}
	s.Found, s.Hint = true, true
	st := sxSt(g)
	st.N++
	g.gainXP(8 + zn.Level)
	where := zn.Name
	switch s.K {
	case "hollow":
		sxCache(g, zn, s)
		sxFirst(g, "hollow", fmt.Sprintf("The wanderer %s found a hidden cache in %s.", g.P.Name, where))
		return
	case "panel":
		sxApplyFound(zn, s)
		g.Msg("{{Y|" + Pick(NewRng(g.W.Seed+zn.Key+"rv"), sxRevealLines["panel"]) + "}}")
		sxFirst(g, "panel", fmt.Sprintf("The wanderer %s found a trapdoor in %s.", g.P.Name, where))
		return
	}
	sxApplyFound(zn, s)
	g.Msg("{{Y|" + Pick(NewRng(g.W.Seed+zn.Key+fmt.Sprint(s.X, s.Y)), sxRevealLines[s.K]) + "}}")
	if s.Order != "" {
		if o := g.OrderByID(s.Order); o != nil {
			g.orderSeen(o)
			g.Msg("{{M|This is a lodge of " + o.Name + ".}}")
			sxFirst(g, "lodge", fmt.Sprintf("The wanderer %s found the hidden lodge of %s in %s.", g.P.Name, o.Name, where))
		}
	}
	text := "found a secret door in " + where
	if s.K == "cut" {
		text = "found a hidden shortcut in " + where
	} else if s.K == "vault" {
		text = "broke into a sealed vault in " + where
	}
	sxFirst(g, s.K, fmt.Sprintf("The wanderer %s %s.", g.P.Name, text))
}

func sxCache(g *Game, zn *Zone, s *sxSecret) {
	r := NewRng(g.W.Seed + ":sx:cache:" + zn.Key + fmt.Sprint(s.X, s.Y))
	tier := zn.Level/3 + 1
	if s.N == "altar" || s.N == "bell" {
		tier++
	}
	line := "A hidden cache."
	if ls := sxContainerNames[s.N]; len(ls) > 0 {
		line = Pick(r, ls)
	}
	g.Msg("{{Y|" + line + "}}")
	it := g.Loot(r, tier)
	g.give(it)
	g.Msg("You take " + it.Display() + ".")
	if r.Chance(0.5) {
		it2 := g.Loot(r, tier)
		g.give(it2)
		g.Msg("You take " + it2.Display() + ".")
	}
	if got := g.cuEarn(25 + zn.Level*10 + r.Int(0, 50)); got != "" {
		g.Msg("You find " + got + ".")
	}
}

// sxBump runs when the player moves toward (x,y), before any other bump rule. It returns true
// when it used the action. Clue inscriptions point at their secret; a hidden panel is stepped on
// (or noticed); a wall or container with a secret is knocked on / tapped at most once an hour.
func sxBump(g *Game, x, y int) bool {
	z := sxHere(g)
	if z == nil {
		return false
	}
	zn := g.Cur
	idx := y*MW + x
	for _, s := range z.S {
		if s.Clue == idx && zn.At(x, y) == TInscription && !s.Hint && !s.Found {
			s.Hint = true
			g.Msg("{{c|The words stay with you.}}")
		}
		if s.Found || s.X != x || s.Y != y {
			continue
		}
		mod := sxMod(g)
		if s.K == "panel" {
			if s.Hint || g.roll2d6Check(g.checkMod("acrobatics")+g.Skills["acrobatics"]+1, sxDC(zn, s)) || g.P.Pow("wings") > 0 {
				sxReveal(g, zn, s)
				g.spend(500)
				return true
			}
			sxDrop(g, zn, s, false)
			return true
		}
		if g.Turn-s.Try < sxCool && s.Tried {
			return false
		}
		s.Try, s.Tried = g.Turn, true
		bonus := 1
		if s.Hint {
			bonus = 4
		}
		if g.roll2d6Check(mod+bonus, sxDC(zn, s)+1) {
			sxReveal(g, zn, s)
			g.spend(1000)
			return true
		}
		if s.K == "hollow" {
			return false // the normal use of the thing goes on
		}
		if s.Hint {
			g.Msg("You knock along the wall; it rings hollow, but you find no catch.")
		} else {
			g.Msg("You rap on the stone. It seems solid.")
		}
		g.spend(1000)
		return true
	}
	return false
}

// sxDrop sends the player down a trapdoor into the vault below (or onto the floor under it).
func sxDrop(g *Game, zn *Zone, s *sxSecret, safe bool) {
	if zn.Z < 1 || zn.Kind != "dungeon" {
		return
	}
	st := sxSt(g)
	s.Found = true
	zn.Set(s.X, s.Y, TTrap)
	g.Msg("{{R|A panel tips under your foot!}}")
	if !safe {
		sxFirst(g, "panel", fmt.Sprintf("The wanderer %s fell through a trapdoor in %s.", g.P.Name, zn.Name))
	}
	below := g.GetZone(zn.WX, zn.WY, zn.ZX, zn.ZY, zn.Z+1)
	var v *sxSecret
	if bz := st.Z[below.Key]; bz != nil {
		for _, o := range bz.S {
			if o.K == "vault" {
				v = o
			}
		}
	}
	lx, ly := s.X, s.Y
	if v != nil {
		lx, ly = v.Ix, v.Iy
	}
	g.enterZone(below, lx, ly, true)
	if v != nil && !v.Found {
		v.Found, v.Hint = true, true
		below.Set(v.X, v.Y, TDoor)
		st.N++
		g.Msg("{{Y|You land in a sealed vault. A catch on the inside opens the door.}}")
		sxFirst(g, "vault", fmt.Sprintf("The wanderer %s fell into a sealed vault in %s.", g.P.Name, below.Name))
	}
	if !safe {
		g.hurt(g.P, g.R.Int(4, 10)+zn.Z, nil, "a fall")
	}
	if !g.Dead {
		g.spend(1000)
	}
}

// sxSearch is the `s` key: find hidden things within 2 tiles; on a found trapdoor, climb down it.
func sxSearch(g *Game) {
	z := sxHere(g)
	if z == nil {
		return
	}
	zn := g.Cur
	p := g.P
	for _, s := range z.S {
		if s.K == "panel" && s.Found && s.X == p.X && s.Y == p.Y {
			g.Msg("You lower yourself through the trapdoor.")
			sxDrop(g, zn, s, true)
			return
		}
	}
	mod := sxMod(g) + 3
	for _, s := range z.S {
		if s.Found || maxi(abs(s.X-p.X), abs(s.Y-p.Y)) > 2 {
			continue
		}
		if g.roll2d6Check(mod, sxDC(zn, s)) {
			sxReveal(g, zn, s)
			if g.Cur != zn || g.Dead {
				return
			}
		} else if !s.Hint && g.R.Chance(0.5) {
			s.Hint = true
			g.Msg("{{c|You are sure something is hidden here, but not how it opens.}}")
		}
	}
}

// sxTurn: once a minute, passive Perception next to an unfound secret.
func sxTurn(g *Game) {
	z := sxHere(g)
	if z == nil || g.P == nil || g.Dead {
		return
	}
	p := g.P
	for _, s := range z.S {
		if s.Found || s.Hint || maxi(abs(s.X-p.X), abs(s.Y-p.Y)) > 1 {
			continue
		}
		if g.roll2d6Check(sxMod(g), sxDC(g.Cur, s)+3) {
			s.Hint = true
			sxHintMsg(g, s)
		}
	}
}

// sxSide: sidebar line for hidden things sensed nearby or pointed out by a rumour.
func sxSide(g *Game) []string {
	z := sxHere(g)
	if z == nil || g.P == nil {
		return nil
	}
	var out []string
	for _, s := range z.S {
		if s.Found {
			continue
		}
		dx, dy := s.X-g.P.X, s.Y-g.P.Y
		d := maxi(abs(dx), abs(dy))
		switch {
		case s.Told && d > 8:
			out = append(out, fmt.Sprintf("{{y|Hidden way: %d %s}}", d, sxAbbrev(sxCompass(dx, dy))))
		case s.Hint && d <= 8:
			out = append(out, fmt.Sprintf("{{c|You sense a secret: %d %s}}", d, sxAbbrev(sxCompass(dx, dy))))
		}
		if len(out) >= 2 {
			break
		}
	}
	return out
}

// ---- the secret-keeper ----

type sxLead struct {
	text string
	key  string
	p    int
}

func sxKeeper(g *Game, a *Actor) bool {
	if g.Cur == nil || g.Cur.Kind != "town" {
		return false
	}
	switch a.Role {
	case "elder", "fence":
		return true
	case "villager", "merchant", "smith", "apothecary":
		return orderFlag(a, "ordm:") != "" || sxRoll(g, fmt.Sprint(a.ID, g.Cur.Key), "keeper") < 0.2
	}
	return false
}

// sxLeads: dungeon levels near here that (by the pure roll or by their state) hold a hidden chamber.
func sxLeads(g *Game) []sxLead {
	st := sxSt(g)
	w := g.W
	var out []sxLead
	for dy := -5; dy <= 5; dy++ {
		for dx := -5; dx <= 5; dx++ {
			wx, wy := g.Cur.WX+dx, g.Cur.WY+dy
			if !w.In(wx, wy) {
				continue
			}
			pp := w.Idx(wx, wy)
			for zy := 0; zy < 3; zy++ {
				for zx := 0; zx < 3; zx++ {
					s := g.siteAt(wx, wy, zx, zy)
					if s == nil || s.Kind != "dungeon" {
						continue
					}
					for z := 1; z <= s.Depth; z++ {
						key := ZoneKey(wx, wy, zx, zy, z)
						if st.Told[key] {
							continue
						}
						if zz := st.Z[key]; zz != nil {
							ok := false
							for _, sc := range zz.S {
								ok = ok || sc.K == "door" && !sc.Found
							}
							if !ok {
								continue
							}
						} else if _, made := g.Zones[key]; made || sxRoll(g, key, "room") >= sxRoomP {
							continue
						}
						out = append(out, sxLead{fmt.Sprintf("%s, near %s: a wall on level %d is not what it seems.", s.Name, w.RegionName(pp), z), key, pp})
					}
				}
			}
		}
	}
	return out
}

// sxTell reveals one secret: first one in this very zone, else a dungeon lead.
func sxTell(g *Game, a *Actor) string {
	st := sxSt(g)
	zn := g.Cur
	if z := st.Z[zn.Key]; z != nil {
		var open []*sxSecret
		for _, s := range z.S {
			if !s.Found && !s.Told {
				open = append(open, s)
			}
		}
		if len(open) > 0 {
			s := open[int(HashStr(g.W.Seed+a.Name+zn.Key))%len(open)]
			s.Told, s.Hint = true, true
			dx, dy := s.X-g.P.X, s.Y-g.P.Y
			what := "a wall that hides a room"
			switch s.K {
			case "hollow":
				what = "a hollow " + s.L + " with something inside"
			case "panel":
				what = "a floor panel that is a trapdoor"
			case "cut":
				what = "a wall that is a door"
			}
			return fmt.Sprintf("\"In this very place there is %s. %s %s of where you stand.\"", what, sxUpper(sxFar(maxi(abs(dx), abs(dy)))), "to the "+sxCompass(dx, dy))
		}
	}
	if leads := sxLeads(g); len(leads) > 0 {
		l := leads[int(HashStr(g.W.Seed+a.Name+fmt.Sprint(g.Turn/1440)))%len(leads)]
		st.Told[l.key] = true
		g.addSecret(l.text, "dungeon", l.p, g.W.Year)
		return "\"I will tell you what the old hands whisper: " + l.text + " Mind it was never mine to tell.\""
	}
	return "\"I know of no hidden ways near here, and I would tell you.\""
}

func sxHasLead(g *Game) bool {
	if z := sxSt(g).Z[g.Cur.Key]; z != nil {
		for _, s := range z.S {
			if !s.Found && !s.Told {
				return true
			}
		}
	}
	return len(sxLeads(g)) > 0
}

func sxTalk(g *Game, a *Actor) []Option {
	if g.W == nil || g.Cur == nil || !sxKeeper(g, a) {
		return nil
	}
	st := sxSt(g)
	id := fmt.Sprint("a", a.ID)
	if st.Asked[id] > 0 {
		return nil
	}
	cost := 15 + g.P.Level*3
	var out []Option
	out = append(out, Option{fmt.Sprintf("{{c|Ask about hidden ways. (%s)}}", g.cuFormat(cost)), func() {
		if !sxHasLead(g) {
			g.talkMenu(Pick(NewRng(g.W.Seed+id), sxKeeperLines) + " \"But nothing near here that I can name.\"")
			return
		}
		if !g.cuSpend(cost) {
			g.talkMenu("\"Such talk is paid in coin, friend.\"")
			return
		}
		st.Asked[id]++
		g.talkMenu(sxTell(g, a))
	}})
	out = append(out, Option{fmt.Sprintf("{{c|Press them for hidden ways. %s}}", g.checkLabel("persuasion", dcChallenging)), func() {
		if !sxHasLead(g) {
			g.talkMenu(Pick(NewRng(g.W.Seed+id), sxKeeperLines) + " \"But nothing near here that I can name.\"")
			return
		}
		st.Asked[id]++
		if g.roll2d6Check(g.checkMod("persuasion"), dcChallenging) {
			g.talkMenu(sxTell(g, a))
			return
		}
		g.talkMenu("\"I have said nothing, and you have heard nothing.\"")
	}})
	return out
}
